{"path": "compute_carrier_otd.py", "content": "import csv
from datetime import datetime

def main():
    filename = 'bookstore_orders.csv'
    stats = {}

    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['fulfillment_status'] != 'Delivered':
                continue
            carrier = row['carrier_name'].strip()
            if not carrier:
                carrier = 'Unknown'
            if carrier not in stats:
                stats[carrier] = {'total': 0, 'ontime': 0}
            stats[carrier]['total'] += 1

            est_str = row['estimated_delivery_date'].strip()
            act_str = row['actual_delivery_date'].strip()
            if not est_str or not act_str:
                continue
            try:
                # Estimated date is just YYYY-MM-DD
                est_date = datetime.strptime(est_str, '%Y-%m-%d').date()
                # Actual may have timestamp, split by space and take first part
                act_date_str = act_str.split()[0]  # YYYY-MM-DD
                act_date = datetime.strptime(act_date_str, '%Y-%m-%d').date()
            except (ValueError, IndexError):
                continue
            if act_date <= est_date:
                stats[carrier]['ontime'] += 1

    results = []
    for carrier, data in stats.items():
        total = data['total']
        ontime = data['ontime']
        ontime_pct = (ontime / total * 100) if total > 0 else 0.0
        results.append({
            'CarrierName': carrier,
            'TotalDelivered': total,
            'OnTimeDelivered': ontime,
            'OnTimePct': round(ontime_pct, 2)
        })

    results.sort(key=lambda x: x['OnTimePct'], reverse=True)

    output_file = 'carrier-otd.csv'
    with open(output_file, 'w', newline='') as f:
        fieldnames = ['CarrierName', 'TotalDelivered', 'OnTimeDelivered', 'OnTimePct']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(results)

    print(f"Written {len(results)} carriers to {output_file}")

if __name__ == '__main__':
    main()"}

{"path": "compute_carrier_delivery_time.py", "content": "import csv
from datetime import datetime

def main():
    filename = 'bookstore_orders.csv'
    # dict: carrier_name -> {'total_hours': float, 'count': int}
    stats = {}

    with open(filename, 'r') as f:
        reader = csv.DictReader(f)
        for row in reader:
            if row['fulfillment_status'] != 'Delivered':
                continue
            carrier = row['carrier_name'].strip()
            if not carrier:
                carrier = 'Unknown'
            if carrier not in stats:
                stats[carrier] = {'total_hours': 0.0, 'count': 0}

            # Parse timestamps
            order_str = row['order_timestamp'].strip()
            actual_str = row['actual_delivery_date'].strip()
            if not order_str or not actual_str:
                continue
            try:
                order_dt = datetime.strptime(order_str, '%Y-%m-%d %H:%M:%S')
                actual_dt = datetime.strptime(actual_str, '%Y-%m-%d %H:%M:%S')
            except ValueError:
                continue

            # Compute difference in hours
            delta = actual_dt - order_dt
            hours = delta.total_seconds() / 3600.0
            # Only consider positive hours? Actually, delivery should be after order, but just in case.
            if hours < 0:
                # If negative, maybe data error; we'll skip or set to 0? Let's skip.
                continue
            stats[carrier]['total_hours'] += hours
            stats[carrier]['count'] += 1

    # Prepare results
    results = []
    for carrier, data in stats.items():
        count = data['count']
        if count == 0:
            continue
        avg_hours = data['total_hours'] / count
        results.append({
            'CarrierName': carrier,
            'DeliveredOrders': count,
            'AvgDeliveryHours': round(avg_hours, 2)
        })

    # Sort by AvgDeliveryHours ascending
    results.sort(key=lambda x: x['AvgDeliveryHours'])

    # Write to CSV
    output_file = 'carrier-delivery-time.csv'
    with open(output_file, 'w', newline='') as f:
        fieldnames = ['CarrierName', 'DeliveredOrders', 'AvgDeliveryHours']
        writer = csv.DictWriter(f, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(results)

    print(f"Written {len(results)} carriers to {output_file}")

if __name__ == '__main__':
    main()"}

